// === Tab: GradCircle ===
class GradCircle {

	constructor(x, y, d, clr, pal) {
		this.x = x;
		this.y = y;
		this.d = d;

		this.clr = clr;
		this.pal = pal;

		this.nn = ~~random(1234321);
		this.td = ~~random(5000, 20000);

		// stroke
		this.f = random();
		this.fd = random(0.01, 0.05);
	}

	update() {
		const t = millis() / this.td;

		this.x = noise(this.nn + 1, t) * width;
		this.y = noise(this.nn + 2, t) * height;
		this.d = noise(this.nn + 3, t) * S * 0.1;

		this.f = fract(this.f + this.fd); // 0..<1
	}

	draw(x, y, d) {
		// stroke(epiColors.getLerpedColorFromPalette(fract(this.f), this.pal));
		stroke(this.clr);
		circle(this.x, this.y, this.d);
	}

}

