// https://github.com/epibyte/p5-epi-colors
const { EpiColors } = EpiColorsPckg;
let epiColors;

let circs, seed, S;

function setup() {
	createCanvas(S=~~(min(innerWidth, innerHeight)*0.95), S);
	describe("Noise Circles on colored background");
	frameRate(60);

	// seed
	seed = ~~random(7654321)
	randomSeed(seed);
	noiseSeed(seed);

	// colors
	epiColors = new EpiColors();
	epiColors.getRandomPalette(true);
	stroke(EpiColors.getColor(epiColors.BG, 64));
	strokeWeight(1.5);
	const BG = epiColors.BG; // console.log(BG);
	fill(BG);
	background(BG);

	// console.log(epiColors.palette);
	circs = [];
	for (let CLR of epiColors.palette) {
		circs.push(new GradCircle(0, 0, 10, CLR, epiColors.palette));
	}

	loop();
}

function draw() {
	for (const circ of circs) {
		circ.update();
		circ.draw();
	}

	// // noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton.left && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}
